import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, toJob, type JobRow } from './db.ts';

const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const insertJob = db.prepare(`INSERT INTO jobs
  (id, input, steps, fail_attempts, status, attempts, progress_completed, available_at, idempotency_key, payload_fingerprint, created_at, updated_at)
  VALUES (?, ?, ?, ?, 'queued', 0, 0, ?, ?, ?, ?, ?)`);
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectHeartbeat = db.prepare('SELECT seen_at FROM heartbeats WHERE name = ?');

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

const invalid = (res: ServerResponse, fields: FieldError[]): void =>
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);

const methodNotAllowed = (res: ServerResponse): void => sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
const notFound = (res: ServerResponse): void => sendError(res, 404, 'not_found', 'Not found.');

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function checkInteger(value: unknown, min: number, max: number, field: string, errors: FieldError[]): number | undefined {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    errors.push({ field, message: `${field} must be an integer.` });
    return undefined;
  }
  if (value < min || value > max) {
    errors.push({ field, message: `${field} must be between ${min} and ${max}.` });
    return undefined;
  }
  return value;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Validates a submission body. Returns the payload with defaults applied, or the field errors. */
function validateBody(req: IncomingMessage, text: string, tooLarge: boolean): { payload?: Payload; errors: FieldError[] } {
  const errors: FieldError[] = [];
  const rawType = req.headers['content-type'];
  const contentType = typeof rawType === 'string' ? rawType : '';
  if (!/^application\/json\b/i.test(contentType)) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
    return { errors };
  }
  if (tooLarge) {
    errors.push({ field: 'body', message: 'Request body is too large.' });
    return { errors };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    errors.push({ field: 'body', message: 'Request body is not valid JSON.' });
    return { errors };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    errors.push({ field: 'body', message: 'Request body must be a JSON object.' });
    return { errors };
  }
  const obj = parsed as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: `Unknown field: ${key}.` });
  }

  let input: string | undefined;
  if (!('input' in obj)) {
    errors.push({ field: 'input', message: 'input is required.' });
  } else if (typeof obj.input !== 'string') {
    errors.push({ field: 'input', message: 'input must be a string.' });
  } else if (obj.input.length < 1 || obj.input.length > 1000) {
    errors.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
  } else if (obj.input.trim().length === 0) {
    errors.push({ field: 'input', message: 'input must not be only whitespace.' });
  } else {
    input = obj.input;
  }

  const steps = 'steps' in obj ? checkInteger(obj.steps, 1, 20, 'steps', errors) : 5;
  const failAttempts = 'failAttempts' in obj ? checkInteger(obj.failAttempts, 0, 5, 'failAttempts', errors) : 0;

  if (errors.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) return { errors };
  return { payload: { input, steps, failAttempts }, errors };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  // A repeated header arrives as an array; treat that as an invalid key rather than guessing.
  const rawKey = req.headers['idempotency-key'];
  const keyHeader = rawKey === undefined ? undefined : typeof rawKey === 'string' ? rawKey : '';
  if (keyHeader !== undefined && !IDEMPOTENCY_KEY.test(keyHeader)) {
    errors.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  const validated = validateBody(req, text, tooLarge);
  errors.push(...validated.errors);
  if (errors.length > 0 || !validated.payload) return invalid(res, errors);
  const payload = validated.payload;
  const fingerprint = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  const key = keyHeader ?? null;

  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== null) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload_fingerprint === fingerprint) return send(res, 200, toJob(existing));
        return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const now = Date.now();
    const iso = new Date(now).toISOString();
    insertJob.run(id, payload.input, payload.steps, payload.failAttempts, now, key, fingerprint, iso, iso);
    const job = selectById.get(id) as JobRow;
    db.exec('COMMIT');
    send(res, 201, toJob(job));
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function health(res: ServerResponse): void {
  const hb = selectHeartbeat.get('worker') as { seen_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.seen_at <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function listJobs(res: ServerResponse): void {
  const rows = selectAll.all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    return notFound(res);
  }
  const row = selectById.get(id) as JobRow | undefined;
  if (!row) return notFound(res);
  send(res, 200, toJob(row));
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';

  if (pathname === '/health') return isGet ? health(res) : methodNotAllowed(res);
  if (pathname === '/') {
    if (!isGet) return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) return isGet ? getJob(res, match[1]!) : methodNotAllowed(res);
  return notFound(res);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error(`request failed: ${e instanceof Error ? e.message : String(e)}`);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2_000).unref();
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

