import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

/** A running attempt holds a lease this long; each step renews it. A dead worker's job is reclaimed after it lapses. */
const LEASE_MS = 2_000;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;

const beatStmt = db.prepare('INSERT INTO heartbeats (name, seen_at) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET seen_at = excluded.seen_at');
const writeHeartbeat = (): void => {
  beatStmt.run('worker', Date.now());
};
writeHeartbeat();
const heartbeatTimer = setInterval(writeHeartbeat, HEARTBEAT_MS);

const claimStmt = db.prepare(`
  SELECT seq, id, input, steps, fail_attempts, attempts FROM jobs
  WHERE (status = 'queued' AND available_at <= ?) OR (status = 'running' AND lease_until < ?)
  ORDER BY seq LIMIT 1`);
const claimUpdateStmt = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, lease_until = ?, updated_at = ?
  WHERE id = ?`);

interface Claimed {
  id: string;
  input: string;
  steps: number;
  fail_attempts: number;
  attempt: number;
}

/** Atomically takes the oldest runnable job and starts a new attempt for it. */
function claim(): Claimed | undefined {
  const now = Date.now();
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = claimStmt.get(now, now) as Pick<JobRow, 'id' | 'input' | 'steps' | 'fail_attempts' | 'attempts'> | undefined;
    if (!row) {
      db.exec('COMMIT');
      return undefined;
    }
    claimUpdateStmt.run(now + LEASE_MS, new Date(now).toISOString(), row.id);
    db.exec('COMMIT');
    return { id: row.id, input: row.input, steps: row.steps, fail_attempts: row.fail_attempts, attempt: row.attempts + 1 };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

const iso = (ms: number): string => new Date(ms).toISOString();

/** Runs one attempt. Every write is guarded by the attempt number so a stale worker cannot clobber a newer attempt. */
async function runAttempt(job: Claimed): Promise<void> {
  // Simulated transient failure: fails at its first step, before any progress.
  if (job.attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    const now = Date.now();
    if (job.attempt >= MAX_ATTEMPTS) {
      db.prepare(`UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, lease_until = 0, updated_at = ?
                  WHERE id = ? AND attempts = ? AND status = 'running'`).run(iso(now), job.id, job.attempt);
    } else {
      db.prepare(`UPDATE jobs SET status = 'queued', available_at = ?, lease_until = 0, updated_at = ?
                  WHERE id = ? AND attempts = ? AND status = 'running'`).run(now + RETRY_DELAY_MS, iso(now), job.id, job.attempt);
    }
    return;
  }

  const progressStmt = db.prepare(`UPDATE jobs SET progress_completed = ?, lease_until = ?, updated_at = ?
                                   WHERE id = ? AND attempts = ? AND status = 'running'`);
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // the lease lapses and the job is reclaimed after restart
    const now = Date.now();
    const result = progressStmt.run(step, now + LEASE_MS, iso(now), job.id, job.attempt);
    if (result.changes === 0) return; // no longer this attempt's job
  }

  const now = Date.now();
  db.prepare(`UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, lease_until = 0, updated_at = ?
              WHERE id = ? AND attempts = ? AND status = 'running'`)
    .run(job.input.toUpperCase(), job.steps, iso(now), job.id, job.attempt);
}

function shutdown(): void {
  stopping = true;
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

console.log('worker started');
while (!stopping) {
  let job: Claimed | undefined;
  try {
    job = claim();
  } catch (e) {
    console.error(`claim failed: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed: ${e instanceof Error ? e.message : String(e)}`);
  }
}

clearInterval(heartbeatTimer);
db.close();
process.exit(0);

